UPDATE edu_marking_task
marking_task_status = #{status}, marking_task_stage = #{stage}, marking_task_total = #{total}, marking_task_done_count = #{done}, marking_task_error = #{error}, marking_task_finish_time = #{now}, update_time = #{now}
WHERE marking_task_task_id = #{taskId}

UPDATE edu_marking_task

    marking_task_answer_sheet_id = #{answerSheetId},
    marking_task_image_path = #{imagePath},
    update_time = #{now}

WHERE marking_task_task_id = #{taskId}

UPDATE edu_marking_task

    marking_task_satisfaction = #{satisfaction},
    update_time = #{now}

WHERE marking_task_task_id = #{taskId}
